import {state,esc,totalProgress} from '../../lib/store.js';import {fields,themes} from '../../data/seed.js';import {panel,bar,button,badge,input,area,select,tabs,empty} from '../pixel/primitives.js';import {taskList} from '../hud/home.js';import {library} from '../library/library.js';
export function research(ui){let body='';if(ui.research==='overview')body=`<div class="grid"><div class="stack">${panel('MASTER THESIS',`<form data-form="thesis">${input('title','论文题目',state.thesisTitle,'text','required maxlength="160"')}<div class="row"><span class="micro muted">TOTAL PROGRESS</span><b class="big-number">${totalProgress()}%</b></div>${bar(totalProgress(),'论文总进度','magenta')}<div class="row wrap">${input('deadline','截止日期',state.deadline,'date','required')}<button class="button primary">保存设置</button></div></form>${['01 / 绪论与研究问题','02 / 理论框架','03 / 文本与案例分析','04 / 翻译策略讨论','05 / 结论'].map((n,i)=>`<div class="chapter"><div class="row"><label for="chapter${i}" class="small">${n}</label><span class="micro cyan">${state.chapters[i]}%</span></div>${bar(state.chapters[i],n)}<input id="chapter${i}" type="range" min="0" max="100" step="5" value="${state.chapters[i]}" data-change="chapter" data-id="${i}" aria-label="${n}进度"></div>`).join('')}`)}</div>${panel('RESEARCH QUESTS',taskList(true))}</div>`;
if(ui.research==='theory')body=`<div class="grid three">${state.theories.map(t=>panel(t.id.toUpperCase(),`<div class="theory"><h3>${esc(t.concept)}</h3><p>${esc(t.description)}</p><form data-form="theory" data-id="${t.id}">${input('position','对应论文位置',t.position)}${area('note','我的理论笔记',t.note)}<button class="button">保存笔记</button></form><div class="tagline cyan">RELATED LITERATURE</div>${state.papers.filter(p=>p.theory.includes(t.id)).map(p=>`<button class="button small" data-action="paper-edit" data-id="${p.id}">${esc(p.title)}</button>`).join('')||'<p>尚无关联文献；可在文献编辑中关联。</p>'}</div>`)).join('')}</div>`;
if(['papers','review'].includes(ui.research)){const isReview=ui.research==='review';let papers=state.papers.filter(p=>(!ui.paperSearch||[p.title,p.author,p.tags,p.object,p.argument,p.relevance,p.note,p.rq].join(' ').toLowerCase().includes(ui.paperSearch.toLowerCase()))&&(!ui.paperTheme||p.theme===ui.paperTheme));body=`<div class="row wrap mb"><p class="muted small">${isReview?'围绕主题比较研究对象、方法与论证；在每篇文献中积累自己的评价。':'示例文献记录可编辑。目录中的文件与研究笔记分别保存，可相互关联。'}</p>${button('＋ 新增文献','paper-edit','','primary')}</div><form class="searchbar" data-form="paper-search"><input name="q" value="${esc(ui.paperSearch)}" placeholder="搜索标题、作者、标签、研究笔记…" aria-label="搜索文献"><select name="theme" aria-label="主题筛选"><option value="">全部主题</option>${themes.map(t=>`<option ${ui.paperTheme===t?'selected':''}>${t}</option>`).join('')}</select><button class="button">筛选</button></form><div class="review-grid">${papers.map(p=>`<article class="paper"><div class="row">${badge(p.theme||'未分类','magenta')}${badge(p.status)}</div><h3 class="mt">${esc(p.title)}</h3><p class="meta">${esc(p.author)} / ${esc(p.year)} / ${esc(p.type)}</p><div class="small muted">${esc(p.tags)}</div>${isReview?`<p class="mt"><b class="cyan">研究对象</b><br>${esc(p.object||'待填写')}</p><p><b class="cyan">核心观点</b><br>${esc(p.argument||'待填写')}</p><p><b class="cyan">与论文的关系</b><br>${esc(p.relevance||'待填写')}</p><p><b class="cyan">我的评价</b><br>${esc(p.evaluation||'待填写')}</p>`:bar(p.progress,'阅读进度')}<p class="micro muted">Theory → ${esc(p.theory||'未关联')}<br>RQ → ${esc(p.rq||'未关联')} / ${esc(p.chapter||'未关联')}</p><div class="actions">${button(isReview?'撰写 / 查看综述':'编辑文献与笔记','paper-edit',`data-id="${p.id}"`)}${p.fileId?button('打开原文','file-open',`data-id="${p.fileId}"`):''}</div></article>`).join('')||empty('没有匹配的文献，试试其他关键词。')}</div>`}
if(ui.research==='library')body=library(ui,true);return tabs([['overview','THESIS / 论文'],['papers','DATABASE / 文献'],['theory','THEORY FRAMEWORK'],['review','LITERATURE REVIEW'],['library','LOCAL LIBRARY']],ui.research,'research')+body}
export function paperForm(id){const p=state.papers.find(p=>p.id===id)||{id:'',progress:0,type:'Book',status:'待读'};return `<form data-form="paper" data-id="${p.id}"><div class="formgrid">${input('title','Title / 标题',p.title,'text','required maxlength="240"')}${input('author','Author / 作者',p.author)}${input('year','Year / 年份',p.year,'number','min="0" max="2200"')}${select('type','Type / 类型',['Book','Article','Essay','Thesis','Note'],p.type)}${select('status','Status / 状态',['待读','阅读中','已读'],p.status)}${input('progress','阅读进度 %',p.progress,'number','min="0" max="100" required')}${input('tags','Tags / 标签（逗号分隔）',p.tags)}${select('theme','综述主题',themes,p.theme)}${input('theory','关联理论（姓名，可多个）',p.theory)}${input('chapter','关联章节',p.chapter)}${input('rq','关联 Research Question',p.rq)}<label class="field"><span>关联本地文件</span><select name="fileId"><option value="">无关联</option>${state.files.map(f=>`<option value="${f.id}" ${p.fileId===f.id?'selected':''}>${esc(f.name)}</option>`).join('')}</select></label>${Object.entries(fields).map(([key,label])=>area(key,label,p[key])).join('')}</div><div class="foot">${p.id?button('删除文献','paper-delete',`data-id="${p.id}"`,'danger'):''}<button class="button primary">保存文献 / 综述</button></div></form>`}
